function openPanel(which){const wrap=$('#modalwrap'),m=$('#modal');if(which==='team'){m.innerHTML=`<div class="modalhead"><div><h2>Your school</h2><p>Raise a team of fearless finned friends.</p></div><button class="close" onclick="closePanel()">×</button></div>${state.fish.length?`<div class="cards">${state.fish.map((f,i)=>`<article class="card"><div class="emoji">${f.emoji}</div><h3>${f.name} <span style="color:#81dccc;font-size:10px">Lv.${f.level}</span></h3><p>${f.rarity} · ♥ ${f.hp}/${f.maxHp}<br>⚔ ${f.power} power · ${f.xp} XP</p><button class="cardbtn" onclick="trainFish(${i})">Train · ◈ 20</button> <button class="cardbtn" onclick="startBattle(${i})">Duel</button></article>`).join('')}</div>`:`<div class="empty"><div style="font-size:38px;margin-bottom:12px">🐟</div><b>Your school is waiting</b>Catch your first fish at one of the glowing fishing spots.</div>`}<div style="display:flex;gap:8px;margin-top:18px"><button class="primary" onclick="startBattle(-1)">Challenge a wild school</button><button class="moves" onclick="closePanel()" style="background:transparent;border:0;color:#9ebdb5">Return</button></div>`}
else if(which==='gear'){m.innerHTML=`<div class="modalhead"><div><h2>Gear & pack</h2><p>Equipment you find can tilt the tide in your favor.</p></div><button class="close" onclick="closePanel()">×</button></div><div class="cards">${state.gear.map((g,i)=>`<article class="card"><div class="emoji">${g.type==='Rod'?'🎣':g.type==='Lure'?'🪝':'🧿'}</div><h3>${g.name}</h3><p>${g.type} · ${g.effect}</p><span class="badge">${g.rarity}${state.equipped===g.name?' · equipped':''}</span><br><button class="cardbtn" onclick="equipGear(${i})">${state.equipped===g.name?'Equipped':'Equip'}</button></article>`).join('')}</div><div style="margin-top:17px;color:#97b7af;font-size:11px">◈ ${state.coins} shells in your pocket</div>`}
else {m.innerHTML=`<div class="modalhead"><div><h2>Field guide</h2><p>Three waters. Countless stories. The rarest fish visit at night.</p></div><button class="close" onclick="closePanel()">×</button></div><div class="cards">${spots.map((s,i)=>`<article class="card"><div class="emoji">${['🌿','🪵','💎'][i]}</div><h3>${s.name}</h3><p>${i===0?'Quiet shallows under the old trees.':i===1?'A weathered pier on the eastern shore.':'A deep, bright pool beneath the cliffs.'}<br><br>Known fish: ${s.fish.join(', ')}</p><span class="badge">${Math.round(Math.hypot(player.position.x-s.x,player.position.z-s.z))}m away</span></article>`).join('')}</div><div style="margin-top:16px;color:#97b7af;font-size:11px">Discovered ${state.fish.length?Object.keys(species).filter(n=>state.fish.some(f=>f.name===n)).length:0} / 7 species · ${state.won} duels won</div>`}
wrap.classList.add('open')}
function closePanel(){$('#modalwrap').classList.remove('open')}
function trainFish(i){const f=state.fish[i];if(state.coins<20){toast('Not enough shells to train');return}if(f.level>=10){toast('This companion has reached max level');return}state.coins-=20;f.level++;f.maxHp+=8;f.hp=Math.min(f.maxHp,f.hp+12);f.power+=2;f.xp+=10;state.trained++;updateHUD();toast(`${f.name} trained to level ${f.level}!`);openPanel('team')}
function equipGear(i){state.equipped=state.gear[i].name;toast(`${state.equipped} equipped`);openPanel('gear')}
function startBattle(i=-1){if(state.fish.length===0){toast('Catch a fish first to make a team');return}closePanel();const own=i>=0?state.fish[i]:state.fish[0];const level=Math.max(own.level,1)+Math.floor(Math.random()*2),pool=['Reedling','Moonscale','Glassfin','Stormjaw'];let enemyName=pool[Math.min(3,Math.floor(Math.random()*pool.length))];if(own.level<2&&Math.random()<.7)enemyName='Sunfin';const data=species[enemyName];state.battle={own,enemy:{name:enemyName,emoji:data.emoji,hp:data.hp+level*5,maxHp:data.hp+level*5,power:data.power+level*2},busy:false};renderBattle();$('#modalwrap').classList.add('open')}
function renderBattle(log='The wild school challenges you!'){const b=state.battle;if(!b)return;$('#modal').innerHTML=`<div class="modalhead"><div><div class="eyebrow" style="color:var(--gold);font-size:10px;letter-spacing:.17em">COMPANION DUEL</div><h2>Make your move</h2><p>Choose a technique. Type matchups are all about timing.</p></div><button class="close" onclick="leaveBattle()">×</button></div><div class="battlefield"><div class="fighter"><div class="bigfish">${b.own.emoji}</div><strong>${b.own.name} · Lv.${b.own.level}</strong><div class="hp"><i style="width:${100*b.own.hp/b.own.maxHp}%"></i></div><small>${Math.max(0,b.own.hp)} / ${b.own.maxHp} HP</small></div><div class="vs">VS</div><div class="fighter"><div class="bigfish">${b.enemy.emoji}</div><strong>Wild ${b.enemy.name}</strong><div class="hp"><i style="width:${100*b.enemy.hp/b.enemy.maxHp}%"></i></div><small>${Math.max(0,b.enemy.hp)} / ${b.enemy.maxHp} HP</small></div></div><div class="battlelog" id="battlelog">${log}</div><div class="moves"><button onclick="battleMove('Splash')">💧 Splash · Quick</button><button onclick="battleMove('Current')">🌊 Current · Strong</button><button onclick="battleMove('Guard')">🛡 Guard · Recover</button></div>`}
function battleMove(move){const b=state.battle;if(!b||b.busy)return;b.busy=true;let log='';if(move==='Guard'){const heal=9+Math.floor(b.own.level*1.5);b.own.hp=Math.min(b.own.maxHp,b.own.hp+heal);log=`${b.own.name} guards and recovers ${heal} HP.`}else{const damage=Math.round(b.own.power*(move==='Current'?1.5:.94)*(0.85+Math.random()*.3));b.enemy.hp=Math.max(0,b.enemy.hp-damage);log=`${b.own.name} uses ${move} for ${damage} damage!`}renderBattle(log);if(b.enemy.hp<=0){setTimeout(()=>battleEnd(true),650);return}setTimeout(()=>{const dmg=Math.max(3,Math.round(b.enemy.power*(.72+Math.random()*.32)));b.own.hp=Math.max(0,b.own.hp-dmg);if(b.own.hp<=0){renderBattle(`Wild ${b.enemy.name} counterattacks for ${dmg}. ${b.own.name} needs a breather.`);setTimeout(()=>battleEnd(false),750)}else{renderBattle(`Wild ${b.enemy.name} counters for ${dmg} damage. Your turn!`);b.busy=false}},650)}
function battleEnd(win){const b=state.battle;if(!b)return;state.battle=null;if(win){state.won++;const coins=25+Math.floor(Math.random()*25);state.coins+=coins;b.own.xp+=species[b.own.name].xp;let loot='';if(Math.random()<.22){const g=gearPool[Math.floor(Math.random()*gearPool.length)];if(!state.gear.some(x=>x.name===g.name)){state.gear.push(g);loot=`<p class="lootbox">✦ Found ${g.name} · ${g.effect}</p>`}}b.own.hp=Math.min(b.own.maxHp,b.own.hp+8);updateHUD();$('#modal').innerHTML=`<div class="modalhead"><div><div style="color:var(--teal);font-size:10px;letter-spacing:.16em">VICTORY</div><h2>That was a fine battle!</h2><p>Your companion stands proud.</p></div><button class="close" onclick="closePanel()">×</button></div><div class="catchbanner"><div class="fishart">🏆</div><div><h3>${b.own.name} wins!</h3><p>+${coins} shells · +${species[b.own.name].xp} XP</p></div></div>${loot}<button class="primary" onclick="closePanel()">Back to the island</button>`}else{b.own.hp=Math.max(1,Math.floor(b.own.maxHp*.45));updateHUD();$('#modal').innerHTML=`<div class="modalhead"><div><div style="color:var(--gold);font-size:10px;letter-spacing:.16em">A CLOSE CALL</div><h2>Better luck next time</h2><p>${b.own.name} retreats to recover.</p></div><button class="close" onclick="closePanel()">×</button></div><button class="primary" onclick="closePanel()">Back to the island</button>`}}
function leaveBattle(){if(state.battle)state.battle=null;closePanel()}
window.openPanel=openPanel;window.closePanel=closePanel;window.trainFish=trainFish;window.equipGear=equipGear;window.startBattle=startBattle;window.battleMove=battleMove;window.leaveBattle=leaveBattle;
$('#modalwrap').addEventListener('pointerdown',e=>{if(e.target===$('#modalwrap'))closePanel()});$('#actionBtn').addEventListener('click',cast);
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key==='e'||e.key==='E'){if(!$('#modalwrap').classList.contains('open'))cast()}if(e.key==='Escape')closePanel()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
document.querySelectorAll('.touchpad button[data-key]').forEach(btn=>{const key=btn.dataset.key;btn.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;btn.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(type=>btn.addEventListener(type,()=>keys[key]=false))});
function update(dt){time+=dt;const pos=waterGeo.attributes.position;for(let i=0;i<pos.count;i++){const x=waterBase[i*3],z=waterBase[i*3+2];pos.array[i*3+1]=Math.sin(x*.14+time*.8)*.16+Math.cos(z*.13-time*.7)*.14}pos.needsUpdate=true;waterGeo.computeVertexNormals();beacons.forEach(({ring,dot},i)=>{ring.rotation.z=time*.3;ring.scale.setScalar(1+Math.sin(time*2+i)*.06);dot.position.y=.2+Math.sin(time*2.7+i)*.19});
if(!$('#modalwrap').classList.contains('open')){const mv=new THREE.Vector3((keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),0,(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0));if(mv.lengthSq()){mv.normalize();playerYaw=Math.atan2(mv.x,mv.z);player.rotation.y=playerYaw;const speed=(keys.shift?10:6)*dt;const nx=player.position.x+mv.x*speed,nz=player.position.z+mv.z*speed;const d=Math.sqrt(nx*nx/(58*58)+nz*nz/(46*46));if(d<.975){player.position.x=nx;player.position.z=nz}else if(Math.abs(nx)<70&&Math.abs(nz)<60){player.position.x=nx;player.position.z=nz}body.position.y=1.05+Math.sin(time*10)*.04;}
if(state.phase==='waiting'&&time>state.biteAt){state.phase='bite';toast('A bite! Press E to set the hook!')}if(state.phase==='fight')reelUpdate(dt);uiAction();}
const target=new THREE.Vector3(player.position.x,0,player.position.z);const camOffset=new THREE.Vector3(0,8.5,12);camOffset.applyAxisAngle(new THREE.Vector3(0,1,0),playerYaw*.2);camera.position.lerp(target.clone().add(camOffset),1-Math.pow(.002,dt));camera.lookAt(player.position.x,1.3,player.position.z);renderer.render(scene,camera)}
function loop(now){const dt=Math.min(.05,(now-last)/1000);last=now;update(dt);requestAnimationFrame(loop)}
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});updateHUD();requestAnimationFrame(loop);
</script>
</body></html>

