cat >> index.html <<'EOF'
const state={coins:120,day:1,fish:[],gear:[{name:'Tidecaller Rod',type:'Rod',rarity:'Uncommon',effect:'+15% bite chance'},{name:'Copper Spinner',type:'Lure',rarity:'Common',effect:'A reliable little lure'}],equipped:'Tidecaller Rod',caught:0,activeSpot:0,phase:'idle',biteAt:0,reel:0,needle:0,needleDir:1,zone:.55,zoneW:.21,won:0,battle:null};const species={Minnow:{emoji:'🐠',color:'#f8d77f',rarity:'Common',hp:30,power:7,xp:12},Sunfin:{emoji:'🐟',color:'#ffad72',rarity:'Common',hp:38,power:8,xp:15},Reedling:{emoji:'🐡',color:'#a9df9e',rarity:'Uncommon',hp:48,power:9,xp:22},Moonscale:{emoji:'🐟',color:'#b8c5ff',rarity:'Rare',hp:58,power:11,xp:32},Glassfin:{emoji:'🐬',color:'#83e6e1',rarity:'Rare',hp:63,power:12,xp:38},Stormjaw:{emoji:'🦈',color:'#ff8a7a',rarity:'Epic',hp:82,power:15,xp:55},Starwhisker:{emoji:'🐉',color:'#e4a4ff',rarity:'Legendary',hp:110,power:19,xp:95}};const gearPool=[{name:'Moonlit Lure',type:'Lure',rarity:'Rare',effect:'+25% chance of rare fish'},{name:'Shellguard Vest',type:'Charm',rarity:'Uncommon',effect:'Companions gain +8 max HP'},{name:'Galehook Rod',type:'Rod',rarity:'Epic',effect:'Shorter waits, tougher catches'},{name:'Lucky Pebble',type:'Charm',rarity:'Uncommon',effect:'Find extra coins after battles'},{name:'Pearl Spinner',type:'Lure',rarity:'Rare',effect:'Pulls in unusual fish'},{name:'Coral Crown',type:'Charm',rarity:'Epic',effect:'A lucky little treasure charm'}];let keys={},last=performance.now(),time=0,toastTimer;
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2500)}function updateHUD(){$('#coinStat').textContent='◈ '+state.coins;$('#fishStat').textContent='🐟 '+state.fish.length;$('#teamCount').textContent=state.fish.length;$('#dayStat').textContent=String(state.day).padStart(2,'0')+' · '+(['Dawn','Day','Dusk','Night'][(state.day-1)%4]);if(!state.caught){$('#objectiveTitle').textContent='Cast your first line';$('#objectiveText').textContent='Explore the shoreline and find a good fishing spot. Every catch is a new companion.'}else if(state.fish.length<3){$('#objectiveTitle').textContent='Build your school';$('#objectiveText').textContent=`You've made ${state.caught} catch${state.caught===1?'':'es'}. Find new waters, collect a team and train your companions.`}else{$('#objectiveTitle').textContent='Become a Tide Champion';$('#objectiveText').textContent=`${state.won} duel${state.won===1?'':'s'} won · Train your team and challenge every wild school.`}}
function nearestSpot(){let best=spots[0],d=Infinity;for(const s of spots){const q=Math.hypot(player.position.x-s.x,player.position.z-s.z);if(q<d){best=s;d=q}}return{spot:best,d}}function uiAction(){const {spot,d}=nearestSpot(),b=$('#actionBtn');if(state.phase==='bite'){b.classList.add('visible');$('#actionTitle').textContent='Set the hook!';$('#actionSub').textContent='E · Now!';return}if(state.phase==='fight'){b.classList.add('visible');$('#actionTitle').textContent='Reel it in';$('#actionSub').textContent='Hold here · reel';return}if(state.phase==='waiting'){b.classList.remove('visible');return}if(d<11){b.classList.add('visible');$('#actionTitle').textContent='Cast a line';$('#actionSub').textContent='E · Fish at '+spot.name}else b.classList.remove('visible');$('#location').textContent=d<15?spot.name:player.position.x>12?'Driftwood Pier':player.position.z<-25?'Blueglass Pool':'Mosslight Cove'}function cast(){if(state.phase==='idle'){const{spot,d}=nearestSpot();if(d>11){toast('Walk closer to a glowing fishing ring first');return}state.activeSpot=spots.indexOf(spot);state.phase='waiting';state.biteAt=time+2.6+Math.random()*3.8;toast('Line away... watch the bobber');rod.rotation.z=-.8;setTimeout(()=>rod.rotation.z=-.42,500)}else if(state.phase==='bite'){state.phase='fight';state.reel=0;state.needle=0;state.needleDir=1;state.zone=Math.random()*.55+.2;state.zoneW=.17;$('#meterbox').classList.add('active');$('#meterTitle').textContent='Something is fighting back!';$('#meterHelp').textContent='Hold SPACE when the marker is in the green.';toast('Hook set! Keep the tension steady.')}}
function finishFish(){state.phase='idle';$('#meterbox').classList.remove('active');const spot=spots[state.activeSpot],list=spot.fish;let name=list[Math.floor(Math.random()*list.length)],rare=state.gear.some(g=>g.name==='Moonlit Lure'||g.name==='Pearl Spinner');if(Math.random()<(rare?.17:.07))name=state.day%4===0?'Starwhisker':'Stormjaw';const spec=species[name],level=1+Math.floor(state.caught/4),fish={id:Date.now()+Math.random(),name,emoji:spec.emoji,rarity:spec.rarity,level,hp:spec.hp+level*5,maxHp:spec.hp+level*5,power:spec.power+level*2,xp:0,location:spot.name};state.fish.push(fish);state.caught++;state.coins+=Math.floor(8+spec.xp*.35);state.day++;let loot=null;if(Math.random()<.38){const g=gearPool[Math.floor(Math.random()*gearPool.length)];if(!state.gear.some(x=>x.name===g.name)){loot=g;state.gear.push(g)}}updateHUD();showCatch(fish,loot)}function reelUpdate(dt){const active=keys.space;state.needle+=state.needleDir*dt*.72;if(state.needle>1){state.needle=1;state.needleDir=-1}if(state.needle<0){state.needle=0;state.needleDir=1}$('#zone').style.left=(state.zone*100)+'%';$('#zone').style.width=(state.zoneW*100)+'%';$('#needle').style.left=`calc(${state.needle*100}% - 2px)`;const inside=state.needle>state.zone&&state.needle<state.zone+state.zoneW;if(active&&inside)state.reel+=dt*.32;else if(active)state.reel-=dt*.13;else state.reel-=dt*.025;state.reel=Math.max(0,state.reel);$('#reelProgress').style.width=(state.reel*100)+'%';if(state.reel>=1)finishFish()}
