--- index.html
+++ index.html
@@ -21,7 +21,7 @@
 function closePanel(){$('#modalwrap').classList.remove('open')}function trainFish(i){const f=state.fish[i];if(state.coins<20){toast('Not enough shells to train');return}if(f.level>=10){toast('This companion has reached max level');return}state.coins-=20;f.level++;f.maxHp+=8;f.hp=Math.min(f.maxHp,f.hp+12);f.power+=2;f.xp+=10;updateHUD();toast(`${f.name} trained to level ${f.level}!`);openPanel('team')}function equipGear(i){state.equipped=state.gear[i].name;toast(`${state.equipped} equipped`);openPanel('gear')}
 function startBattle(i=-1){if(!state.fish.length){toast('Catch a fish first to make a team');return}closePanel();const own=i>=0?state.fish[i]:state.fish[0],level=Math.max(own.level,1)+Math.floor(Math.random()*2),pool=['Reedling','Moonscale','Glassfin','Stormjaw'];let en=pool[Math.floor(Math.random()*pool.length)];if(own.level<2&&Math.random()<.7)en='Sunfin';const d=species[en];state.battle={own,enemy:{name:en,emoji:d.emoji,hp:d.hp+level*5,maxHp:d.hp+level*5,power:d.power+level*2},busy:false};renderBattle();$('#modalwrap').classList.add('open')}function renderBattle(log='The wild school challenges you!'){const b=state.battle;if(!b)return;$('#modal').innerHTML=`<div class="modalhead"><div><div style="color:var(--gold);font-size:10px;letter-spacing:.17em">COMPANION DUEL</div><h2>Make your move</h2><p>Choose a technique. Type matchups are all about timing.</p></div><button class="close" onclick="leaveBattle()">×</button></div><div class="battlefield"><div class="fighter"><div class="bigfish">${b.own.emoji}</div><strong>${b.own.name} · Lv.${b.own.level}</strong><div class="hp"><i style="width:${100*b.own.hp/b.own.maxHp}%"></i></div><small>${Math.max(0,b.own.hp)} / ${b.own.maxHp} HP</small></div><div class="vs">VS</div><div class="fighter"><div class="bigfish">${b.enemy.emoji}</div><strong>Wild ${b.enemy.name}</strong><div class="hp"><i style="width:${100*b.enemy.hp/b.enemy.maxHp}%"></i></div><small>${Math.max(0,b.enemy.hp)} / ${b.enemy.maxHp} HP</small></div></div><div class="battlelog">${log}</div><div class="moves"><button onclick="battleMove('Splash')">💧 Splash · Quick</button><button onclick="battleMove('Current')">🌊 Current · Strong</button><button onclick="battleMove('Guard')">🛡 Guard · Recover</button></div>`}function battleMove(move){const b=state.battle;if(!b||b.busy)return;b.busy=true;let log;if(move==='Guard'){const heal=9+Math.floor(b.own.level*1.5);b.own.hp=Math.min(b.own.maxHp,b.own.hp+heal);log=`${b.own.name} guards and recovers ${heal} HP.`}else{const damage=Math.round(b.own.power*(move==='Current'?1.5:.94)*(.85+Math.random()*.3));b.enemy.hp=Math.max(0,b.enemy.hp-damage);log=`${b.own.name} uses ${move} for ${damage} damage!`}renderBattle(log);if(b.enemy.hp<=0){setTimeout(()=>battleEnd(true),650);return}setTimeout(()=>{const dmg=Math.max(3,Math.round(b.enemy.power*(.72+Math.random()*.32)));b.own.hp=Math.max(0,b.own.hp-dmg);if(b.own.hp<=0){renderBattle(`Wild ${b.enemy.name} counterattacks for ${dmg}. ${b.own.name} needs a breather.`);setTimeout(()=>battleEnd(false),750)}else{renderBattle(`Wild ${b.enemy.name} counters for ${dmg} damage. Your turn!`);b.busy=false}},650)}
